catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading) {
        return;
    }

    var policyValue = (newValue || '').trim();

    g_form.hideFieldMsg('policy_number_text', true);

    if (!policyValue) {
        g_form.clearValue('policyholder_name');
        g_form.clearValue('coverage_limit');
        g_form.clearValue('policy_status');
        return;
    }

    var ga = new GlideAjax('x_snc_insurance_0.IRISPolicyLookup');

    ga.addParam('sysparm_name', 'getPolicyDetails');
    ga.addParam('sysparm_policy_sys_id', policyValue);

    ga.getXMLAnswer(function(answer) {

        // Ignore stale responses
        if ((g_form.getValue('policy_number_text') || '').trim() !== policyValue) {
            return;
        }

        if (!answer) {
            g_form.showFieldMsg(
                'policy_number_text',
                'No response from policy lookup. Please try again.',
                'error'
            );
            return;
        }

        try {
            var result = JSON.parse(answer);

            if (result.found === true) {
                g_form.setValue(
                    'policyholder_name',
                    result.policyholder_name || ''
                );

                g_form.setValue(
                    'coverage_limit',
                    result.coverage_limit || ''
                );

                g_form.setValue(
                    'policy_status',
                    result.policy_status || ''
                );

                g_form.hideFieldMsg('policy_number_text', true);

            } else {
                g_form.clearValue('policyholder_name');
                g_form.clearValue('coverage_limit');
                g_form.clearValue('policy_status');

                g_form.showFieldMsg(
                    'policy_number_text',
                    'This policy number was not found for your account. Please check it.',
                    'error'
                );
            }

        } catch (e) {
            g_form.showFieldMsg(
                'policy_number_text',
                'Error reading policy details. Please try again.',
                'error'
            );
        }
    });
}
